# Analyze current test input to extract the pattern
print("Test input:")
for row in grid:
    print(row)

# Detectors: 8s
# Find dividers
for i, row in enumerate(grid):
    if all(cell == 8 for cell in row):
        print(f"\nHorizontal 8-divider at row {i}")
for j, col_vals in enumerate(zip(*grid)):
    if all(cell == 8 for cell in col_vals):
        print(f"Vertical 8-divider at col {j}")

# The pattern is in the quadrant that has non-4, non-8 cells
# Based on demo, pattern quadrant is the one with the most variety/colors

# Find all non-4, non-8 cells
pattern_cells = []
for i in range(len(grid)):
    for j in range(len(grid[0])):
        val = grid[i][j]
        if val not in [4, 8]:
            pattern_cells.append((i, j, val))

print(f"\nPattern cells (non-4, non-8): {pattern_cells}")

# Determine which quadrant the pattern is in
# Dividers at row 4 and col 9
# Quadrants:
# Top-left: rows 0-3, cols 0-8
# Top-right: rows 0-3, cols 10-18
# Bottom-left: rows 5-8, cols 0-8
# Bottom-right: rows 5-8, cols 10-18

quadrant_counts = {
    'top-left': 0,
    'top-right': 0,
    'bottom-left': 0,
    'bottom-right': 0
}

for i, j, val in pattern_cells:
    if i < 4 and j < 9:
        quadrant_counts['top-left'] += 1
    elif i < 4 and j >= 10:
        quadrant_counts['top-right'] += 1
    elif i >= 5 and j < 9:
        quadrant_counts['bottom-left'] += 1
    elif i >= 5 and j >= 10:
        quadrant_counts['bottom-right'] += 1

print(f"\nPattern distribution: {quadrant_counts}")

# Extract the pattern from the quadrant with pattern cells
# pattern is at rows 5-8, cols 0-8 (bottom-left)
# Need to extract 4x9 rows x 9 cols

pattern_height = 4  # rows 5-8
pattern_width = 9   # cols 0-8

pattern = [grid[5+r][0:9] for r in range(4)]
print(f"\nPattern data (bottom-left):")
for row in pattern:
    print(row)

# Output should copy this pattern to all 4 quadrants
# Create output grid
output_height = 9
output_width = 19

output = [['4' for _ in range(output_width)] for _ in range(output_height)]

# Place dividers (same as input)
for j in range(output_width):
    output[4][j] = '8'
for i in range(output_height):
    output[i][9] = '8'

# Pattern is 4x9 in bottom-left (rows 5-8, cols 0-8)
# Same for all quadrants
# Top-left: rows 0-3, cols 0-8
# Top-right: rows 0-3, cols 10-18  
# Bottom-left: rows 5-8, cols 0-8
# Bottom-right: rows 5-8, cols 10-18

# Let me place pattern in top-left
for r in range(4):
    for c in range(9):
        output[r][c] = str(pattern[r][c])

# Top-right (shifted right by 10)
for r in range(4):
    for c in range(9):
        output[r][c+10] = str(pattern[r][c])

# Bottom-left (shifted down by 5)
for r in range(4):
    for c in range(9):
        output[5+r][c] = str(pattern[r][c])

# Bottom-right (shifted down by 5, right by 10)
for r in range(4):
    for c in range(9):
        output[5+r][c+10] = str(pattern[r][c])

print("\nOutput grid:")
for row in output:
    print(' '.join(row))
